div.p:
Convention : la tour déclare ses modèles (une ligne chacun) ;
              chaque site statique dépose un memoire.json à sa racine.
              Une nouvelle webapp n'a qu'à faire l'un des deux.

body.script:
//
(function () {
  "use strict";
  var q = document.getElementById("q");
  var go = document.getElementById("go");
  var res = document.getElementById("resultats");
  var compte = document.getElementById("compte");
  var cat = document.getElementById("catalogue");

  function esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;")
      .replace(/>/g, "&gt;").replace(/"/g, "&quot;");
  }

  function rappel() {
    var v = q.value.trim();
    if (!v) { return; }
    fetch("/tour/memoire/rappel?q=" + encodeURIComponent(v),
          { credentials: "same-origin" })
      .then(function (r) { return r.json(); })
      .then(function (d) {
        if (d.error) { compte.textContent = d.error; return; }
        var liste = d.entrees || [];
        compte.textContent = liste.length
          ? liste.length + " entrée(s) rappelée(s) pour « " + v + " »"
          : "Aucune entrée rappelée pour « " + v + " »";
        if (!liste.length) {
          res.innerHTML = '<h2>Résultats</h2><p class="empty">Rien trouvé — la mémoire ne connaît pas encore ce sujet.</p>';
          return;
        }
        res.innerHTML = '<h2>Résultats</h2>' + liste.map(function (e) {
          return '<div class="entree">' +
            '<div class="t"><a href="' + esc(e.url) + '" target="_blank">' + esc(e.titre) + "</a></div>" +
            (e.resume ? '<div class="r">' + esc(e.resume) + "</div>" : "") +
            '<div class="m"><span class="badge ' + (e.source === "tour" ? "tour" : "site") + '">' +
            esc(e.source) + "</span> · " + esc(e.type) +
            (e.date ? " · " + esc(e.date) : "") +
            (e.statut ? " · " + esc(e.statut) : "") + "</div></div>";
        }).join("");
      })
      .catch(function () {
        res.innerHTML = '<h2>Résultats</h2><p class="empty">Le robinet ne répond pas.</p>';
      });
  }

  if (go) { go.addEventListener("click", rappel); }
  if (q) {
    q.addEventListener("keydown", function (e) { if (e.key === "Enter") { rappel(); } });
  }

  fetch("/tour/memoire/data", { credentials: "same-origin" })
    .then(function (r) { return r.json(); })
    .then(function (d) {
      if (d.error || !cat) { return; }
      var html = "";
      (d.modeles || []).forEach(function (m) {
        html += "<li><b>" + esc(m.label) + "</b> — modèle <code>" + esc(m.model) + "</code></li>";
      });
      (d.statiques || []).forEach(function (e) {
        html += "<li><b>" + esc(e.source) + "</b> — " + esc(e.titre) + "</li>";
      });
      cat.innerHTML = html ||
        "<li class='empty'>Aucune source indexée.</li>";
    })
    .catch(function () { /* silencieux : le catalogue est un bonus */ });
})();
//
